const format=(v,type)=>v==null?'—':type==='market'?marketName(v):type==='date'?date(v):type==='money'?num(v,2):type==='number'?num(v):typeof v==='boolean'?(v?'是':'否'):Array.isArray(v)?v.map(attributionLabel).join('、'):String(attributionLabel(v));
