 const valid=(saved==='name:asc')||(['orders','filled','volume','realizedPnl','pnl'].includes(metric)&&c.columns.some(col=>col.key===metric)&&['asc','desc'].includes(direction));
 return businessSortModes[key]=valid?saved:fallback;
