function mergedTrendChange(row,key,previousKey){
 if(row.dataQuality?.incomplete||row.previousDataQuality?.incomplete)return '数据不完整 · 暂不判断涨跌';
 if(!previousKey||row[key]==null||row[previousKey]==null)return '无上期可比数据';
 const current=Number(row[key]),previous=Number(row[previousKey]);
 if(!Number.isFinite(current)||!Number.isFinite(previous))return '无上期可比数据';
 if(previous===0)return current===0?'0.00%（持平）':'上期为 0，无法计算百分比';
 const change=(current-previous)/Math.abs(previous)*100;
 const transition=previous<0&&current>0?' · 转盈':previous>0&&current<0?' · 转亏':'';
 return (change>0?'+':'')+num(change,2)+'%'+transition;
}
function mergedTrendTooltip(c,row){
 const keys=[...new Set([...(c.tooltipSeriesKeys||c.seriesKeys||[]),...(c.unitGroups||[]).flatMap(group=>group.seriesKeys),...(c.previousKey?[c.previousKey]:[])])];
 const current=keys.filter(key=>!key.startsWith('previous'));
 const prior=key=>keys.find(candidate=>candidate==='previous'+key[0].toUpperCase()+key.slice(1))||(key===c.key?c.previousKey:null);
 const hasPrior=current.some(key=>prior(key));
 const unit=key=>c.tooltipUnits?.[key]||(c.unitGroups||[]).find(group=>group.seriesKeys.includes(key))?.unit||c.unit;
 const value=key=>key&&row[key]!=null?num(row[key],['人','个','笔'].includes(unit(key))?0:2)+' '+unit(key):'—';
 const color=key=>{const group=c.unitGroups?.find(group=>group.seriesKeys.includes(key))||c,colors=['#397bf1','#8959e9','#18b1a2','#f78b26','#e44396','#08a75c','#11a6c2','#8495ac'];return trendBarModes[chartModeKey(c)]&&c.signedSeries?.includes(key)?Number(row[key])<0?'#db4b45':'#38865a':c.seriesColors?.[key]||colors[Math.max(0,(group.seriesKeys||[]).indexOf(key))%colors.length];};
 return `<strong>${esc(row.date)}（北京时间）</strong><table class="merged-trend-tooltip"><thead><tr><th>指标</th><th>本期</th>${hasPrior?'<th>上期按天对齐</th><th>较上期变化</th>':''}</tr></thead><tbody>${current.map(key=>`<tr><th>${esc(c.tooltipLabels?.[key]||c.seriesLabels?.[key]||key)}</th><td style="color:${color(key)}">${esc(value(key))}</td>${hasPrior?`<td style="color:${color(prior(key))}">${esc(value(prior(key)))}</td><td class="merged-trend-change"><strong>${esc(mergedTrendChange(row,key,prior(key)))}</strong></td>`:''}</tr>`).join('')}</tbody></table>`;
}

